insert into public.stages (id, course_id, title, summary, source_url, source_label, sort_order) values ($qa$pemweb-x2$qa$, $qa$pemweb$qa$, $qa$Mengenal HTML$qa$, $qa$<h3>Definisi HTML</h3>
<p><strong>HTML (HyperText Markup Language)</strong> adalah bahasa markup untuk menyusun <strong>konten dan struktur</strong> halaman web menggunakan <strong>tag</strong>. Browser membaca tag lalu menampilkan konten sesuai maknanya. HTML <strong>bukan</strong> bahasa pemrograman.</p>
<h3>Elemen, Tag, dan Atribut</h3>
<ul>
<li><strong>Elemen</strong> = tag pembuka + konten + tag penutup, mis. <code>&lt;p&gt;Halo&lt;/p&gt;</code>.</li>
<li><strong>Atribut</strong> memberi info tambahan pada tag, mis. <code>&lt;a href="https://itera.ac.id"&gt;</code>.</li>
<li><strong>Void element</strong> (elemen kosong): tidak punya konten &amp; tag penutup, mis. <code>&lt;img&gt;</code>, <code>&lt;br&gt;</code>, <code>&lt;input&gt;</code>.</li>
<li><strong>Nested element</strong>: elemen di dalam elemen lain; harus ditutup dengan urutan yang benar.</li>
</ul>
<h3>Struktur Dasar Dokumen</h3>
<p><code>&lt;!DOCTYPE html&gt;</code> → <code>&lt;html&gt;</code> → <code>&lt;head&gt;</code> (metadata, <code>&lt;title&gt;</code>) dan <code>&lt;body&gt;</code> (konten yang tampil).</p>
<h3>Tag-Tag Penting</h3>
<table>
<tr><th>Tag</th><th>Fungsi</th><th>Atribut umum</th></tr>
<tr><td><code>&lt;h1&gt;</code>–<code>&lt;h6&gt;</code></td><td>Heading, h1 paling penting</td><td>-</td></tr>
<tr><td><code>&lt;a&gt;</code></td><td>Hyperlink</td><td><code>href</code>, <code>target="_blank"</code> (tab baru)</td></tr>
<tr><td><code>&lt;img&gt;</code></td><td>Menyisipkan gambar</td><td><code>src</code>, <code>alt</code>, <code>width</code>/<code>height</code></td></tr>
<tr><td><code>&lt;table&gt;</code>, <code>&lt;tr&gt;</code>, <code>&lt;th&gt;</code>, <code>&lt;td&gt;</code></td><td>Tabel data</td><td><code>colspan</code>, <code>rowspan</code></td></tr>
<tr><td><code>&lt;form&gt;</code>, <code>&lt;input&gt;</code></td><td>Formulir</td><td><code>action</code>, <code>method</code>, <code>type</code></td></tr>
</table>
<h3>HTML Semantik</h3>
<p>Tag yang <strong>bermakna</strong>: <code>&lt;header&gt;</code>, <code>&lt;nav&gt;</code>, <code>&lt;main&gt;</code>, <code>&lt;article&gt;</code>, <code>&lt;section&gt;</code>, <code>&lt;aside&gt;</code>, <code>&lt;footer&gt;</code>. Manfaatnya: <strong>aksesibilitas</strong> (screen reader) dan <strong>SEO</strong> (mesin pencari paham struktur halaman).</p>
<h3>HTML5 &amp; Pipeline Rendering</h3>
<ul>
<li><strong>HTML5</strong> membawa fitur native: <code>&lt;canvas&gt;</code> (gambar 2D), <code>&lt;audio&gt;</code>, <code>&lt;video&gt;</code> — tanpa plugin.</li>
<li><strong>Pipeline rendering browser:</strong> HTML diurai jadi <strong>DOM</strong> → CSS diurai jadi <strong>CSSOM</strong> → keduanya digabung menjadi <strong>render tree</strong> → ditampilkan.</li>
<li><strong>Validasi:</strong> gunakan W3C Validator agar kode standar, konsisten, dan kompatibel lintas browser.</li>
</ul>$qa$, null, null, 2) on conflict (id) do update set course_id = excluded.course_id, title = excluded.title, summary = excluded.summary, source_url = excluded.source_url, source_label = excluded.source_label, sort_order = excluded.sort_order;
