insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x2-c1$qa$, $qa$pemweb-x2$qa$, $qa$checkpoint$qa$, $qa$Manakah pernyataan yang benar tentang HTML?$qa$, $qa$["HTML adalah bahasa pemrograman untuk logika aplikasi", "HTML adalah bahasa markup untuk menyusun struktur dan konten halaman web", "HTML berfungsi mengatur tampilan warna dan layout", "HTML dieksekusi di server sebelum dikirim ke browser"]$qa$::jsonb, 1, $qa$HTML (HyperText Markup Language) menyusun struktur/konten lewat tag; ia bukan bahasa pemrograman.$qa$, 1) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x2-c2$qa$, $qa$pemweb-x2$qa$, $qa$checkpoint$qa$, $qa$Manakah yang termasuk void element?$qa$, $qa$["<p>", "<div>", "<img>", "<a>"]$qa$::jsonb, 2, $qa$Void element tidak punya konten dan tag penutup, contoh <img>, <br>, <input>.$qa$, 2) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x2-c3$qa$, $qa$pemweb-x2$qa$, $qa$checkpoint$qa$, $qa$Apa manfaat utama memakai HTML semantik seperti <article> dan <nav>?$qa$, $qa$["Membuat halaman dimuat lebih cepat", "Membantu aksesibilitas (screen reader) dan SEO", "Menggantikan kebutuhan CSS", "Mengamankan data formulir"]$qa$::jsonb, 1, $qa$Tag semantik bermakna sehingga mesin pencari dan screen reader memahami struktur halaman.$qa$, 3) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x2-b1$qa$, $qa$pemweb-x2$qa$, $qa$battle$qa$, $qa$Manakah yang termasuk void element (tidak memerlukan tag penutup)?$qa$, $qa$["<p>", "<div>", "<img>", "<a>"]$qa$::jsonb, 2, $qa$Void element seperti img, br, dan input tidak memiliki konten sehingga tidak butuh tag penutup.$qa$, 1) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
insert into public.questions (id, stage_id, kind, question, options, correct_index, explanation, sort_order) values ($qa$pemweb-x2-b2$qa$, $qa$pemweb-x2$qa$, $qa$battle$qa$, $qa$Fungsi atribut alt pada tag img adalah...$qa$, $qa$["Mengatur lebar gambar", "Teks alternatif yang tampil jika gambar gagal dimuat", "Membuat gambar menjadi link", "Mengubah format file gambar"]$qa$::jsonb, 1, $qa$Atribut alt menyediakan teks pengganti saat gambar tidak bisa ditampilkan, sekaligus membantu aksesibilitas.$qa$, 2) on conflict (id) do update set stage_id = excluded.stage_id, kind = excluded.kind, question = excluded.question, options = excluded.options, correct_index = excluded.correct_index, explanation = excluded.explanation, sort_order = excluded.sort_order;
